using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Documents; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Documents; [Authorize] public class DetailsModel:PageModel{private readonly OrcaFacilDbContext _db; private readonly ICurrentUserService _current; private readonly DocumentService _service; public Document? Document{get;private set;} public string? PublicUrl{get;private set;} public DetailsModel(OrcaFacilDbContext db,ICurrentUserService current,DocumentService service){_db=db;_current=current;_service=service;} public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){Document=await _db.Documents.Include(d=>d.Items).SingleOrDefaultAsync(d=>d.Id==id&&d.UserId==_current.UserId&&!d.IsDeleted,ct); return Document is null?NotFound():Page();} public async Task<IActionResult> OnPostDeleteAsync(Guid id,CancellationToken ct){await _service.DeleteAsync(new(_current.UserId,id),ct); return RedirectToPage("/Documents/Index");} public async Task<IActionResult> OnPostDuplicateAsync(Guid id,CancellationToken ct){var r=await _service.DuplicateAsync(new(_current.UserId,id),ct); return r.Succeeded?RedirectToPage("/Documents/Edit",new{id=r.Value}):RedirectToPage();} public async Task<IActionResult> OnPostPublicLinkAsync(Guid id,CancellationToken ct){var r=await _service.GeneratePublicLinkAsync(_current.UserId,id,ct); if(r.Succeeded) TempData["Success"]=$"Link público: /p/{r.Value}"; return RedirectToPage(new{id});}}
